import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Upgrade to 1.0.0-beta4","description":"","frontmatter":{},"headers":[],"relativePath":"self-hosting/upgrade.md","filePath":"self-hosting/upgrade.md","lastUpdated":1792570296000}'),n={name:"self-hosting/upgrade.md"};function r(o,e,p,d,l,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="upgrade-to-1-0-0-beta4" tabindex="-1">Upgrade to 1.0.0-beta4 <a class="header-anchor" href="#upgrade-to-1-0-0-beta4" aria-label="Permalink to &quot;Upgrade to 1.0.0-beta4&quot;">​</a></h1><p>Already running an earlier 1.0 beta? <a href="#from-an-earlier-1-0-beta">Upgrade in place</a>; no migration is needed.</p><p>Compared with 0.2, the 1.0 line is a complete architectural refactor with breaking changes to the Python runtime, frontend, local storage, and integrations. It provides an explicit user-data migration path; old Python imports, internal APIs, and frontend endpoints are not compatibility contracts. The rest of this guide moves a 0.2 installation to 1.0.0-beta4.</p><h2 id="what-changes-for-a-0-2-installation" tabindex="-1">What changes for a 0.2 installation <a class="header-anchor" href="#what-changes-for-a-0-2-installation" aria-label="Permalink to &quot;What changes for a 0.2 installation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Requirement when upgrading from 0.2</th></tr></thead><tbody><tr><td>Runtime</td><td>Use Python 3.12 or newer; install into a fresh environment</td></tr><tr><td>Entry points</td><td>Use <code>paperseek serve</code> and the current six-command CLI; update scripts that call retired commands</td></tr><tr><td>Integrations</td><td>Update clients for <code>/api/v1</code>; install the same-version <code>paperseek-mcp</code> when needed</td></tr><tr><td>Configuration</td><td>Convert supported old environment names once, review ignored values, then load the new names into the process</td></tr><tr><td>Storage</td><td>Migrate the 0.2 database explicitly; new SQLite schema changes are managed by Alembic</td></tr><tr><td>Running tasks</td><td>Finish or cancel old work before switching versions; do not assume an unfinished old task or checkpoint can resume under the new workflow</td></tr></tbody></table><p>The new application separates the research core, task services, and deployment adapters. Saved runs now use worker leases, events, checkpoints, and artifacts. These changes are described in the <a href="./../changelog#v1-0-0-beta">changelog</a> and <a href="./../developers/contributing#architecture">architecture notes</a>.</p><p>This guide covers a Community installation. Using PaperSeek online does not require running a local database migration.</p><h2 id="before-upgrading" tabindex="-1">Before upgrading <a class="header-anchor" href="#before-upgrading" aria-label="Permalink to &quot;Before upgrading&quot;">​</a></h2><ol><li>Finish or cancel active work, then stop the old application and any worker.</li><li>Back up its database, artifacts, and configuration outside the checkout.</li><li>Install 1.0.0-beta4 in a separate environment.</li><li>Test the migrated copy before replacing the old installation.</li></ol><p>Keep the original backup until you have checked saved questions, result counts, and exports.</p><h2 id="migrate-a-0-2-database" tabindex="-1">Migrate a 0.2 database <a class="header-anchor" href="#migrate-a-0-2-database" aria-label="Permalink to &quot;Migrate a 0.2 database&quot;">​</a></h2><p>Use explicit source, destination, and backup paths:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-v0.2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /backup/old-paperseek.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --database</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/paperseek/paperseek.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /backup/old-paperseek.v02.db</span></span></code></pre></div><p>Without a separate <code>--database</code>, the command targets the source path. Supplying an explicit destination makes a rehearsal easier to inspect.</p><p>Review the migration report. Do not replace the original database with an unverified output.</p><h2 id="convert-an-old-environment-file" tabindex="-1">Convert an old environment file <a class="header-anchor" href="#convert-an-old-environment-file" aria-label="Permalink to &quot;Convert an old environment file&quot;">​</a></h2><p>Configuration conversion is a separate operation:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --legacy-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /backup/old.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/paperseek.env</span></span></code></pre></div><p>Inspect converted and ignored settings. The output is not automatically loaded by <code>paperseek serve</code>; export the current variables into its process environment or load them through your service manager.</p><p>Do not combine <code>--legacy-env</code> with database-migration flags. Keep real keys and migration reports outside Git.</p><h2 id="verify-the-new-installation" tabindex="-1">Verify the new installation <a class="header-anchor" href="#verify-the-new-installation" aria-label="Permalink to &quot;Verify the new installation&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --database</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/paperseek/paperseek.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --database</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/paperseek/paperseek.db</span></span></code></pre></div><p>Open history, inspect a saved run, export its results, and make a small new search with your configured provider.</p><h2 id="from-an-earlier-1-0-beta" tabindex="-1">From an earlier 1.0 beta <a class="header-anchor" href="#from-an-earlier-1-0-beta" aria-label="Permalink to &quot;From an earlier 1.0 beta {#from-an-earlier-1-0-beta}&quot;">​</a></h2><p>1.0.0-beta4 keeps the database schema, configuration, and command line of the earlier 1.0 beta, so it upgrades in place without a migration.</p><ol><li><p>Finish or cancel active work, stop the service and any worker, and back up the database.</p></li><li><p>Install the new version:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;paperseek==1.0.0b4&quot;</span></span></code></pre></div><p>Add <code>&quot;paperseek-mcp==1.0.0b4&quot;</code> to the same command if you use the MCP adapter. With Docker, set <code>PAPERSEEK_VERSION</code> to <code>1.0.0-beta4</code> in <code>.env</code>, then run <code>docker compose pull</code> and <code>docker compose up -d</code>.</p></li><li><p>Start the service and check <code>paperseek version</code>.</p></li></ol><p>After the upgrade, up to four searches and reviews run at the same time; set <code>PAPERSEEK_MAX_CONCURRENT_RUNS</code> to change that. If your network needs a proxy to reach models or data sources, set it up in <strong>Settings › Data sources › Network proxy</strong> or with the variables in <a href="./../reference/configuration#network-proxy">Network proxy</a>.</p><p>Reviews that have no written sections yet extract evidence again the next time you generate the outline, which uses your writing model once more. Reviews with written sections keep their evidence.</p><p>The supplied <code>compose.yaml</code> publishes the port on 127.0.0.1 only. If you open PaperSeek from another device, take the new <code>compose.yaml</code>, set <code>PAPERSEEK_HOST=0.0.0.0</code> in <code>.env</code>, and protect access as described in <a href="./#network-access">Network access</a>.</p><h2 id="roll-back" tabindex="-1">Roll back <a class="header-anchor" href="#roll-back" aria-label="Permalink to &quot;Roll back&quot;">​</a></h2><p>Stop the new processes first. Restore the complete pre-upgrade data and the corresponding old application environment. Do not point an older runtime at a database that has already been migrated forward.</p>`,31)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
